package com.pabonaki.repo;import com.pabonaki.model.Order;import org.springframework.data.mongodb.repository.MongoRepository;import java.util.List;import java.util.Optional;public interface OrderRepository extends MongoRepository<Order,String>{List<Order> findByUserIdOrderByCreatedAtDesc(String userId);List<Order> findAllByOrderByCreatedAtDesc();Optional<Order> findByIdAndUserId(String id,String userId);Optional<Order> findByTransactionId(String transactionId);}